from pwn import *
import string
import re

def roll_byte(b, n):
    return ((b << n) | (b >> (8-n))) & 0xFF

def unroll_byte(b, n):
    return ((b >> n) | (b << (8-n))) & 0xFF

def try_decode_section(data, start_offset, size=512):
    section = data[start_offset:start_offset+size]
    results = []

    # Try various single-byte XOR keys
    for key in range(256):
        decoded = bytes(b ^ key for b in section)
        if b'csaw_ctf{' in decoded:
            results.append(f"XOR key {hex(key)}: {decoded}")

    # Try rolling bits
    for roll in range(1, 8):
        decoded = bytes(roll_byte(b, roll) for b in section)
        if b'csaw_ctf{' in decoded:
            results.append(f"ROL {roll}: {decoded}")
        decoded = bytes(unroll_byte(b, roll) for b in section)
        if b'csaw_ctf{' in decoded:
            results.append(f"ROR {roll}: {decoded}")

    # Try adding/subtracting values
    for key in range(256):
        decoded = bytes((b + key) & 0xFF for b in section)
        if b'csaw_ctf{' in decoded:
            results.append(f"ADD {hex(key)}: {decoded}")
        decoded = bytes((b - key) & 0xFF for b in section)
        if b'csaw_ctf{' in decoded:
            results.append(f"SUB {hex(key)}: {decoded}")

    return results

def try_find_flag_pattern(data):
    # Look for partial flag patterns
    patterns = [
        b'csaw_',
        b'ctf{',
        b'flag',
        bytes([ord(c) ^ 0x42 for c in 'csaw_ctf{']),  # Common XOR key
    ]

    for i in range(0, len(data)-8):
        block = data[i:i+32]
        for pattern in patterns:
            pos = block.find(pattern)
            if pos != -1:
                print(f"Found pattern {pattern} at offset {hex(i+pos)}")
                print(f"Surrounding bytes: {block.hex()}")

def main():
    with open('cell.pkg', 'rb') as f:
        data = f.read()

    # First try to find any flag-like patterns
    print("Looking for flag patterns...")
    try_find_flag_pattern(data)

    # Try decoding around the region where we saw "ew{/n"
    interesting_offsets = [0x150, 0x158, 0x15c, 0x160]

    for offset in interesting_offsets:
        print(f"\nTrying decode at offset {hex(offset)}:")
        results = try_decode_section(data, offset)
        for result in results:
            print(result)

if __name__ == '__main__':
    main()

