from pwn import *
import struct

def rotate_left(value, shift):
    return ((value << shift) | (value >> (8 - shift))) & 0xFF

def rotate_right(value, shift):
    return ((value >> shift) | (value << (8 - shift))) & 0xFF

def decrypt_cell_specific(data, key):
    results = []
    # Cell processor works with 128-bit vectors
    for i in range(0, len(data)-16, 16):
        block = data[i:i+16]

        # Try different Cell-specific operations
        # 1. Rotate pattern based on key
        dec1 = bytes(rotate_left(b, k % 8) for b, k in zip(block, cycle(key)))

        # 2. Rotate with carry between bytes
        dec2 = bytearray(len(block))
        carry = 0
        for j, (b, k) in enumerate(zip(block, cycle(key))):
            rotated = rotate_left(b, k % 8)
            dec2[j] = (rotated + carry) & 0xFF
            carry = rotated >> 7

        # 3. Cell's byte shuffle pattern
        dec3 = bytearray(len(block))
        for j in range(0, len(block), 4):
            chunk = block[j:j+4]
            if len(chunk) == 4:
                # Shuffle bytes based on key pattern
                k = key[j % len(key)]
                pattern = k % 24  # 24 possible 4-byte permutations
                if pattern < 6:
                    dec3[j:j+4] = chunk[pattern:] + chunk[:pattern]
                else:
                    dec3[j:j+4] = chunk[::-1]  # reverse as fallback

        # 4. SIMD-style parallel operation
        dec4 = bytes((b + (k * (i % 4))) & 0xFF for i, (b, k) in enumerate(zip(block, cycle(key))))

        # Check results
        for dec in [bytes(dec1), bytes(dec2), bytes(dec3), dec4]:
            try:
                text = dec.decode('ascii', errors='ignore')
                if 'csaw_ctf{' in text:
                    end_idx = text.find('}', text.find('csaw_ctf{'))
                    if end_idx != -1:
                        flag = text[text.find('csaw_ctf{'):end_idx+1]
                        results.append(flag)
            except:
                continue

        # Try reverse operations
        dec5 = bytes(rotate_right(b, k % 8) for b, k in zip(block, cycle(key)))
        try:
            text = dec5.decode('ascii', errors='ignore')
            if 'csaw_ctf{' in text:
                end_idx = text.find('}', text.find('csaw_ctf{'))
                if end_idx != -1:
                    flag = text[text.find('csaw_ctf{'):end_idx+1]
                    results.append(flag)
        except:
            pass

    return list(set(results))  # Remove duplicates

def main():
