    with open('/home/ctfplayer/ctf_files/chal/cell.pkg', 'rb') as f:
        data = f.read()

    print("[+] File loaded, size:", len(data))

    # Original key and variations
    orig_key = [139, 229, 193, 84, 44, 145, 173, 111, 252]
    key_variations = [
        ('Original', orig_key),
        ('Reversed', orig_key[::-1]),
        ('Rotated +1', orig_key[1:] + orig_key[:1]),
        ('Rotated -1', orig_key[-1:] + orig_key[:-1])
    ]

    # Process important sections
    sections = [
        (0x60, 0x1000),    # Start of data
        (0x1000, 0x2000),  # Common section for code
        (0x2000, 0x3000),  # Another common section
    ]

    all_flags = set()

    for start, end in sections:
        if start >= len(data):
