#!/usr/bin/env python3
from pwn import *
import struct
from itertools import cycle

def try_decrypt(encrypted_text, key):
    decrypted = []
    # We know we have "csaw_ctf{a1~l[-N*cDl}"
    # Let's try to decrypt from this known pattern

    # Try various Cell-inspired operations
    for i, (c, k) in enumerate(zip(encrypted_text, cycle(key))):
        # Basic operations
        dec1 = (c + k) & 0xFF  # Addition
        dec2 = (c - k) & 0xFF  # Subtraction
        dec3 = c ^ k          # XOR
        dec4 = (c + (k << (i % 4))) & 0xFF  # Shifting add
        dec5 = (c - (k >> (i % 4))) & 0xFF  # Shifting subtract

        # Store all possibilities
        decrypted.append([dec1, dec2, dec3, dec4, dec5])

    # Try to reconstruct potential flags
    results = []

    # Get all possible combinations for a single position
    for ops in zip(*decrypted):
        try:
            text = ''.join(chr(x) if 32 <= x <= 126 else '.' for x in ops)
            if 'csaw_ctf{' in text:
                end = text.find('}', text.find('csaw_ctf{'))
                if end != -1:
                    flag = text[text.find('csaw_ctf{'):end+1]
                    if all(c.isprintable() for c in flag):
                        results.append(flag)
        except:
            continue

    return list(set(results))

def main():
    # Original encrypted flag: "csaw_ctf{a1~l[-N*cDl}"
    encrypted = [ord(c) for c in "csaw_ctf{a1~l[-N*cDl}"]
    key = [139, 229, 193, 84, 44, 145, 173, 111, 252]

    print("[+] Trying to decrypt known flag pattern")
    print(f"[*] Key: {key}")

    # Try different key arrangements
    key_variations = [
        ('Original', key),
        ('Reversed', key[::-1]),
        ('Rotated +1', key[1:] + key[:1]),
        ('Rotated -1', key[-1:] + key[:-1]),
        ('XORed', [x ^ 0xFF for x in key]),
        ('Negated', [0xFF - x for x in key])
    ]

    all_flags = set()

    for key_name, key_var in key_variations:
        print(f"\n[*] Trying {key_name} key variation")
        flags = try_decrypt(encrypted, key_var)

        for flag in flags:
            print(f"[!] Potential flag found: {flag}")
            all_flags.add(flag)

    # Also try with the PKG file
    with open('/home/ctfplayer/ctf_files/chal/cell.pkg', 'rb') as f:
        data = f.read()

    print("\n[+] Analyzing PKG file")
    # Look for flag pattern in important offsets
    offsets = [0x60, 0x100, 0x200, 0x300, 0x400]

    for offset in offsets:
        if offset >= len(data):
            continue

        chunk = data[offset:offset + 1024]
        for key_name, key_var in key_variations:
            flags = try_decrypt(chunk, key_var)
            for flag in flags:
                if flag not in all_flags:
                    print(f"[!] New potential flag found at offset 0x{offset:x}: {flag}")
                    all_flags.add(flag)

    if all_flags:
        print("\n[+] All unique flags found:")
        for flag in sorted(all_flags):
            print(f"    {flag}")
    else:
        print("\n[-] No valid flags found")

    # Try some Cell-specific analysis on the known encrypted text
    print("\n[+] Attempting Cell-specific analysis")
    # Cell processors work with 128-bit vectors
    encrypted_chunks = [encrypted[i:i+16] for i in range(0, len(encrypted), 16)]

    for chunk in encrypted_chunks:
        if len(chunk) < 16:
            chunk = chunk + [0] * (16 - len(chunk))

        # Try Cell vector operations
        for key_var in [key, key[::-1]]:
            # Vector shuffle
            shuffled = []
            for i in range(0, 16, 4):
                k = key_var[i % len(key_var)]
                pattern = k % 4
                sub_chunk = chunk[i:i+4]
                shuffled.extend(sub_chunk[pattern:] + sub_chunk[:pattern])

            try:
                text = ''.join(chr(x) if 32 <= x <= 126 else '.' for x in shuffled)
                if 'csaw_ctf{' in text:
                    end = text.find('}', text.find('csaw_ctf{'))
                    if end != -1:
                        flag = text[text.find('csaw_ctf{'):end+1]
                        if flag not in all_flags and all(c.isprintable() for c in flag):
                            print(f"[!] New flag found through Cell vector operation: {flag}")
                            all_flags.add(flag)
            except:
                continue

if __name__ == '__main__':
    main()
